import javax.swing.JList;
import javax.swing.ListModel;

public class ShoppingListPanelTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        for (java.awt.Component c : root.getComponents()) {
            if (name.equals(c.getName())) {
                return c;
            }
            if (c instanceof java.awt.Container) {
                java.awt.Component found = find((java.awt.Container) c, name);
                if (found != null) {
                    return found;
                }
            }
        }
        return null;
    }

    static String elementAt(ListModel<?> model, int index) {
        if (model == null || index < 0 || index >= model.getSize()) {
            return "none";
        }
        return String.valueOf(model.getElementAt(index));
    }

    public static void main(String[] args) {
        try {
            ShoppingListPanel panel = new ShoppingListPanel();
            java.awt.Component c = find(panel, "list");
            JList<?> list = c instanceof JList ? (JList<?>) c : null;
            ListModel<?> model = list == null ? null : list.getModel();

            check("a JList named list exists", true, model != null);
            check("an empty list", "0/null", panel.itemCount() + "/" + panel.selectedItem());

            panel.addItem("milk");
            panel.addItem("eggs");
            panel.addItem("bread");

            check("itemCount after three additions", 3, panel.itemCount());
            check("the model really holds them", "3/eggs", model == null ? null
                    : model.getSize() + "/" + elementAt(model, 1));

            panel.selectItem("bread");
            check("selecting by value", "bread/2", panel.selectedItem() + "/"
                    + (list == null ? "?" : list.getSelectedIndex()));

            panel.selectItem("caviar");
            check("selecting something absent clears the selection", null, panel.selectedItem());

            check("removing a present item", true, panel.removeItem("eggs"));
            check("the list shrank, and an absent item removes nothing", "2/bread/false",
                    panel.itemCount() + "/" + elementAt(model, 1) + "/" + panel.removeItem("caviar"));
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected " + t.getClass().getSimpleName() + ": " + t.getMessage());
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

